svg.script:
(function () {
  var svg = document.documentElement;
  var group = document.getElementById("ccgarden-scrubber");
  var input = document.getElementById("ccgarden-scrubber-input");
  var label = document.getElementById("ccgarden-scrubber-label");
  var duration = 5;
  var keyTimes = [0,0.2,0.4,0.6,0.8,1];
  var dayLabels = ["Jul 26, 2026","Jul 27, 2026","Jul 28, 2026","Jul 29, 2026","Jul 30, 2026","Jul 31, 2026"];
  var paused = false;
  function reveal() {
    group.style.opacity = "1";
    group.style.pointerEvents = "auto";
  }
  function seek(dayIndex) {
    if (!paused) { svg.pauseAnimations(); paused = true; }
    svg.setCurrentTime(keyTimes[dayIndex] * duration);
    label.textContent = dayLabels[dayIndex];
  }
  input.addEventListener("input", function () {
    seek(parseInt(input.value, 10));
  });
  window.setTimeout(reveal, duration * 1000 + 150);
})();
